import inspect, hera.analysis as A
print([n for n in dir(A) if not n.startswith('_')])
for n in ['sdh_onset','sdh_fft','field_invB','fan_grids','resistance_grids','open_run','summarize_run','luttinger_frequency','plot_raw']:
